const $=s=>document.querySelector(s), euro=n=>new Intl.NumberFormat('en-IE',{style:'currency',currency:'EUR',maximumFractionDigits:2}).format(n),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let raw;try{raw=JSON.parse(localStorage.getItem('budventure-v2')||localStorage.getItem('budventure-v1')||'null')}catch{}let state=Budget.normalize(raw),step=state.created?5:0,category='Food',selected=null,rating=5,receipt=null,receiptBusy=false,reviewDraft={},query='I want to try a local dish.',maxPrice=35;const names=['Plan your trip','Your budget','Ask your guide','Local discoveries','Share an experience','My profile'];
const id=()=>globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2);
function persist(){try{localStorage.setItem('budventure-v2',JSON.stringify(state));return true}catch{toast('Storage is full or unavailable. Your changes could not be saved.');return false}}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4500)}
function go(n){step=n;render();window.scrollTo({top:0,behavior:'smooth'})}
function heading(k,title,desc){const labels=['Plan','Budget','Ask','Discover','Share'];return `<div class="journeyrail" aria-label="How it works">${labels.map((n,i)=>`<button class="${i===step?'current':i<step?'complete':''}" onclick="go(${i})" ${i===step?'aria-current="step"':''}><span>${i<step?'✓':i+1}</span>${n}</button>`).join('')}<button class="${step===5?'current':''}" onclick="go(5)"><span>♡</span>Profile</button></div><div class="heading"><div><div class="eyebrow">${k}</div><h1>${title.replaceAll('<br>',' ')}</h1><p class="intro">${desc}</p></div><span class="chapterbadge">${step===5?'YOUR STORY':`0${step+1} / 05`}</span></div>`}
function actions(next,label){return `<div class="actions"><button class="secondary" onclick="go(${Math.max(0,step-1)})">← Back</button><button class="primary" onclick="go(${next})">${label} →</button></div>`}
function render(){let c=Budget.calculate(state);$('#breadcrumb').textContent=step===5?'YOUR PERSONAL SPACE':`${step<2?'BEFORE YOU GO':'YOUR CITY, YOUR WAY'} / STEP ${step+1}`;$('#nav').innerHTML=names.map((n,i)=>`<button class="${step===i?'active':''}" onclick="go(${i})"><span>${i===5?'♡':i+1}</span>${n}</button>`).join('');$('#app').setAttribute('data-screen',step);$('#app').innerHTML=[plan,overview,chat,discovery,review,profile][step](c);$('#personName').textContent=state.created?state.name:'Your journey starts here';$('#personInitial').textContent=state.name?state.name[0].toUpperCase():'B';bind()}
function status(c){if(c.ended)return '<div class="notice">Your trip has ended. Your history is saved in My profile. Create a separate trip in a future version to keep budgets independent.</div>';if(c.short)return `<div class="notice warning" role="alert"><b>This budget does not cover your selected lifestyle.</b><br>You need about ${euro(c.short)} more for this ${state.months}-month plan (estimated total ${euro(c.total)}). ${state.budget<c.minimum?`Even the lowest-cost demo setup is approximately ${euro(c.minimum)}. Try a shorter stay, more funding or another city.`:'Try Budget Saver and a student residence, or increase your budget.'}<br><small>Saving a draft does not make this plan financially feasible.</small></div>`;return `<div class="notice"><b>Your estimated living costs fit your budget.</b><br>There is ${euro(state.budget-c.total)} beyond the estimated plan, which already includes an emergency reserve.</div>`}
function forecast(c){return `<section class="panel forecastpanel"><div class="eyebrow">${c.hasTrend?'BASED ON YOUR RECENT SPENDING':'EARLY ESTIMATE · BUILDING YOUR HISTORY'}</div><div class="forecastsignal" aria-hidden="true">↗</div><h2 style="margin-bottom:10px">${c.projectedGap>0?'A small course correction?':'Room to keep exploring.'}</h2><p class="intro">${c.hasTrend?`Your last ${Math.min(14,c.elapsed)} completed days suggest ${euro(c.rate)} per day in flexible spending.`:'Until you log spending on at least 3 completed days, this forecast uses your selected lifestyle estimate.'}</p><div class="ticket"><div><span>Estimated trip-end total</span><b>${euro(c.projected)}</b></div><div><span>${c.projectedGap?'Predicted funding gap':'Predicted cushion'}</span><b>${euro(c.projectedGap||Math.max(0,state.budget-c.projected))}</b></div><div><span>Safe daily flexible allowance</span><b>${euro(c.daily)}</b></div></div><details class="explanation"><summary>How this forecast works</summary><p class="tiny">${c.before?'Your trip has not started. ':''}${c.ended?'The trip is complete. ':''}Remaining allowance reserves unpaid housing, transport and emergencies. Log these payments under their own categories to avoid double counting. Forecasts assume you log all spending; they are estimates, not guarantees.</p></details></section>`}
function plan(c){return heading('01 / A little planning, a big adventure','Your new city.<br><em>Your kind of life.</em>','Create your student profile and a plan that fits the way you want to live.')+`<div class="layout planlayout"><div><form id="planForm" onsubmit="createProfile(event)"><section class="panel tripfields"><h2 class="sectiontitle"><span>↗</span> First, a little about you</h2><div class="fields"><label style="grid-column:1/-1">Your name<input id="name" name="name" required maxlength="60" autocomplete="given-name" value="${esc(state.name)}" placeholder="What should we call you?"></label><label>Country<select id="country">${Object.values(Budget.cities).map(c=>`<option ${c.country===Budget.cities[state.city].country?'selected':''}>${c.country}</option>`).join('')}</select></label><label>City<select id="city">${Object.keys(Budget.cities).map(x=>`<option ${x===state.city?'selected':''}>${x}</option>`).join('')}</select></label><label>Trip starts<input id="start" type="date" required value="${state.start}"></label><label>Length of stay<select id="months">${[1,2,3,4,5,6,9,12].map(x=>`<option value="${x}" ${x===state.months?'selected':''}>${x} month${x>1?'s':''}</option>`).join('')}</select></label><label>Total trip budget (€)<input id="budget" type="number" min="1" max="1000000" step="0.01" required value="${state.budget}"><small>Include your scholarship and savings.</small></label><label>Housing preference<select id="housing">${['Student residence','Shared apartment','Private apartment'].map(x=>`<option ${x===state.housing?'selected':''}>${x}</option>`).join('')}</select></label></div></section><section class="panel lifestylepanel"><h2 class="sectiontitle"><span>♡</span> Which life feels like you?</h2><p class="hint" style="margin:-10px 0 20px">Your priorities, not your income. You can change your mind.</p><div class="profilegrid">${Budget.lifestyles.map((p,i)=>`<button type="button" aria-pressed="${state.profile===i}" class="profile ${state.profile===i?'selected':''}" onclick="chooseLifestyle(${i})"><span class="radio"></span><span class="icon">${p[1]}</span><b>${p[0]}</b><p>${p[2]}</p></button>`).join('')}</div></section>${status(c)}<div class="actions"><small>Your profile and experiences stay together on this browser.</small><button class="primary" type="submit">${state.created?'Update profile':c.short?'Create profile & review draft':'Create my profile'} ↗</button></div></form></div><div><section class="summary"><img class="cityart" src="assets/student-city.svg" alt="Illustrated student neighbourhood with a bicycle and leafy streets"><div class="eyebrow">YOUR TRIP AT A GLANCE</div><h3>${state.city} is waiting.</h3><p>New streets, new friends.<br>A more confident beginning.</p><div class="ticket"><div><span>Destination</span><b>${state.city}, ${Budget.cities[state.city].country}</b></div><div><span>Duration</span><b>${c.days} days</b></div><div><span>Lifestyle</span><b>${Budget.lifestyles[state.profile][0]}</b></div></div><small>YOUR MONTHLY BUDGET</small><div class="big">${euro(state.budget/state.months)}</div><div class="tag">Estimated monthly need: ${euro(c.monthly)}</div></section><div class="greenbox"><b>A plan with breathing room</b><br>We include a 10% emergency reserve. Flights, visas and housing deposits are extra.</div><p class="tiny">Illustrative city estimates, not live prices. One trip per profile in this MVP.</p></div></div>`}
function chooseLifestyle(i){captureName();state.profile=i;render()}
function captureName(){if($('#name'))state.name=$('#name').value.trim()}
function bind(){['city','months','budget','housing','start'].forEach(k=>{let el=$('#'+k);if(el)el.onchange=()=>{captureName();let v=['months','budget'].includes(k)?Number(el.value):el.value;if(k==='budget'&&(!Number.isFinite(v)||v<1||v>1000000)){toast('Enter a budget between €1 and €1,000,000.');el.value=state.budget;return}if(k==='start'&&(!v||!Number.isFinite(Budget.day(v))))return;if(['city','months','start'].includes(k)&&state.expenses.length){toast('Your trip has spending history. Keep its dates and city to preserve an accurate budget.');el.value=state[k];return}state[k]=v;render()}});if($('#country'))$('#country').onchange=e=>{captureName();if(state.expenses.length){toast('Your trip has spending history. Its destination is locked.');render();return}state.city=Object.keys(Budget.cities).find(k=>Budget.cities[k].country===e.target.value);render()}}
function createProfile(e){e.preventDefault();captureName();if(!state.name){toast('Please enter your name.');return}state.created=true;if(persist()){go(1);toast('Your profile is ready. Experiences will appear in My profile.')}}
function stats(c){return `<div class="stats"><div class="stat"><small>UNSPENT BUDGET</small><strong>${euro(c.remaining)}</strong><small>${euro(c.spent)} spent so far</small></div><div class="stat"><small>SAFE DAILY ALLOWANCE</small><strong>${euro(c.daily)}</strong><small>${c.remainingDays} days remaining</small></div><div class="stat"><small>EXPERIENCES SAVED</small><strong>${state.reviews.length}</strong><small>Automatically added to your profile</small></div></div>`}
function budgetChart(c){let offset=0;const colors=['#7655b8','#abc984','#b6a0d2','#d7e5c4','#c2b5da','#e7dbe8'];return `<div class="allocation"><div class="donut"><svg viewBox="0 0 160 160" role="img" aria-label="Monthly budget distribution. ${c.rows.map(r=>r[0]+': '+euro(r[1])).join(', ')}">${c.rows.map((r,i)=>{let pct=r[1]/c.monthly*100,part=`<circle cx="80" cy="80" r="61" pathLength="100" fill="none" stroke="${colors[i]}" stroke-width="17" stroke-dasharray="${pct} ${100-pct}" stroke-dashoffset="${-offset}" transform="rotate(-90 80 80)"/>`;offset+=pct;return part}).join('')}</svg><div><small>PER MONTH</small><b>${euro(c.monthly)}</b></div></div><div class="allocationlegend">${c.rows.map((r,i)=>`<div><span><i style="background:${colors[i]}"></i>${r[0]}</span><b>${euro(r[1])}</b></div>`).join('')}</div></div>`}
function overview(c){return heading('02 / Your personal roadmap',`${state.city}, <em>with a plan.</em>`,`${Budget.lifestyles[state.profile][0]} · ${state.months} months · ${state.housing}`)+status(c)+stats(c)+`<div class="layout dashboardlayout"><div><section class="panel"><h2 class="sectiontitle">Where your budget goes <span>Monthly estimate</span></h2>${budgetChart(c)}</section>${expenseForm(c)}</div><div>${forecast(c)}</div></div>${actions(2,'Find something to do')}`}

function expenseForm(c){return `<details class="panel expensedrawer"><summary>＋ Log your everyday spending</summary>${!state.created?'<p>Create your profile before recording expenses.</p><button class="primary" onclick="go(0)">Create profile →</button>':c.before||c.ended?'<p>Spending entries are available during your trip. Your history remains visible in My profile.</p>':`<form onsubmit="addExpense(event)" class="fields"><label>Description<input name="title" required maxlength="80" placeholder="e.g. groceries"></label><label>Amount (€)<input name="amount" required type="number" min="0.01" max="100000" step="0.01"></label><label>Category<select name="category">${['Food','Activities','Personal','Housing','Transport'].map(x=>`<option>${x}</option>`).join('')}</select></label><label>Date<input name="date" type="date" required min="${state.start}" max="${Budget.today()}" value="${Budget.today()}"></label><button class="secondary">+ Add expense</button></form>`}</details>`}
function checkVisit(date,c){return date>=state.start&&date<c.end&&date<=Budget.today()}
function addExpense(e){e.preventDefault();let d=new FormData(e.target),amount=Number(d.get('amount')),date=d.get('date');if(!state.created||!checkVisit(date,Budget.calculate(state))||!Number.isFinite(amount)||amount<=0){toast('Enter a valid expense within your trip, no later than today.');return}state.expenses.push({id:id(),title:String(d.get('title')).trim(),category:d.get('category'),amount,date});if(persist()){render();toast('Expense saved. Your allowance and forecast have been updated.')}else state.expenses.pop()}
function chat(c){let q=query.toLowerCase();category=/coffee|café|cafe|study/.test(q)?'Cafés':/activity|museum|park|walk|cinema/.test(q)?'Activities':'Food';let target=Math.min(category==='Cafés'?5:category==='Activities'?10:15,c.daily*.5);return heading('03 / Your city companion','What feels like<br><em>a good day?</em>','Tell us what you have in mind. Your guide keeps your budget in view.')+`<div class="guidelayout"><div class="guidecontext"><img src="assets/student-city.svg" alt="Student city illustration"><div class="eyebrow">YOUR CITY COMPANION</div><h3>${state.city}, at your pace.</h3><p>Make room for small discoveries.</p><div class="guidelimit"><small>TODAY’S FLEXIBLE ALLOWANCE</small><b>${euro(c.daily)}</b></div><small>${Budget.lifestyles[state.profile][0]}</small></div><div class="chat"><div class="notice">${state.city} · ${Budget.lifestyles[state.profile][0]} · Daily allowance ${euro(c.daily)}</div><div class="bubble">${esc(query)}</div><div class="response"><div class="eyebrow">YOUR BUDVENTURE GUIDE</div><h2>${category==='Food'?'A little taste of local life.':category==='Cafés'?'Find your next coffee spot.':'Make room for a new memory.'}</h2><p>${c.daily<=0?'Your flexible budget is currently exhausted. Choose free activities and review your funding before making a paid visit.':category==='Food'?`${state.city==='Milan'?'Try a panzerotto or a small plate of risotto.':`Look for a student lunch menu in ${state.city}.`} Aim for around ${euro(target)} so you keep room for the rest of your day.`:category==='Cafés'?`Look for neighbourhood cafés with student offers. A ${euro(target)} limit helps keep the break affordable.`:`Start with free parks or student cultural tickets. Keep paid activities around ${euro(target)}.`}</p><details class="explanation"><summary>About your guide</summary><p class="tiny">Local category-based suggestions, not live AI search. Advice updates from your recorded expenses.</p></details><button class="primary" onclick="maxPrice=Math.max(0,Math.floor(Budget.calculate(state).daily/2));go(3)">Show places within my budget ↗</button></div><div class="chips">${['I want to try a local dish.','Coffee and a place to study.','A free activity or museum.'].map(q=>`<button onclick='ask(${JSON.stringify(q)})'>${q}</button>`).join('')}</div><form class="chatinput" onsubmit="event.preventDefault();ask(this.elements.request.value)"><input name="request" required maxlength="300" aria-label="What would you like to do?" placeholder="What do you have in mind?"><button class="primary">Send ↑</button></form></div></div>${actions(3,'Explore local places')}`}
function ask(q){if(q.trim()){query=q.trim();render()}}
function places(){let rows=category==='Food'?[['Neighbourhood Kitchen','🍝','Local dishes · Student lunch',12,4.7],['Campus Table','🥗','A simple, generous lunch',8,4.6],['The Slow Table','🍲','A more comfortable dinner',25,4.8]]:category==='Cafés'?[['Corner Coffee','☕','Study tables · Fresh coffee',4,4.7],['Campus Café','🥐','An everyday student break',3,4.5],['Garden Café','🍵','A quiet garden table',7,4.8]]:[['City Park','🌳','A free walk outdoors',0,4.8],['Small Gallery','🎨','Student admission',6,4.6],['Film Night','🎬','Independent cinema',10,4.7]];return rows.map((p,i)=>({id:`${state.city}-${category}-${i}`,name:p[0],icon:p[1],desc:p[2],price:p[3],score:p[4],category,city:state.city}))}
function discovery(c){let list=places().filter(p=>p.price<=maxPrice);return heading('04 / Little local discoveries','Less tourist.<br><em>More you.</em>',`Illustrative places in ${state.city}, with your daily allowance in mind.`)+`<div class="notice">All places, prices and ratings below are fictional demo data, not verified local listings.</div><div class="filter"><label>Looking for<select onchange="category=this.value;render()">${['Food','Cafés','Activities'].map(x=>`<option ${category===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Maximum price (€)<input type="number" min="0" value="${maxPrice}" onchange="maxPrice=Math.max(0,Number(this.value)||0);render()"></label><button class="secondary" onclick="maxPrice=Math.max(0,Math.floor(Budget.calculate(state).daily/2));render()">Match my budget</button></div><div class="cards">${list.map(p=>`<article class="place"><div class="placeart"><img src="assets/${p.category==='Food'?'dining':p.category==='Cafés'?'coffee':'park'}.jpg" alt="${p.category==='Food'?'Illustrative restaurant interior':p.category==='Cafés'?'Illustrative coffee photo':'Illustrative green park'}" loading="lazy"><span class="photolabel">Illustrative photo</span><span class="placepin">${p.icon}</span></div><div class="placebody"><span class="badge ${p.price>c.daily*.5?'pricewarning':''}">${p.price===0?'Free':p.price<=c.daily*.5?'Within your meal allowance':p.price<=c.daily?'Uses most of today’s allowance':'Above today’s allowance'}</span><h3>${p.name}</h3><p>${p.desc}<br>${p.city} · Demo listing</p><div class="price"><span>${euro(p.price)}<small>estimated per person</small></span><span>★ ${p.score}<small>illustrative rating</small></span></div><button class="primary" onclick="selectPlace('${p.id}')">Choose this place →</button></div></article>`).join('')||'<section class="panel"><h3>No paid places fit this limit.</h3><p>Keep your plan on track with a free activity instead.</p><button class="primary" onclick="category=\'Activities\';maxPrice=0;render()">Find free activities →</button></section>'}</div><p class="tiny">Choosing a place is not a payment. Your budget changes when you record the visit. Sponsored placements are not part of this demo.</p>${actions(5,'See my profile')}`}
function selectPlace(placeId){selected=places().find(p=>p.id===placeId);reviewDraft={};receipt=null;rating=5;go(4)}
function rememberReview(){let f=$('#reviewForm');if(!f)return;reviewDraft={comment:f.elements.comment.value,amount:f.elements.amount.value,date:f.elements.date.value}}
function setRating(i){rating=i;document.querySelectorAll('.stars button').forEach((b,j)=>{b.classList.toggle('on',j<i);b.setAttribute('aria-pressed',String(j+1===i))})}
function review(c){if(!state.created)return heading('05 / Your experience matters','A place for<br><em>your memories.</em>','Create a profile first so your visits, spending and experiences stay together.')+'<button class="primary" onclick="go(0)">Create my profile →</button>';if(!selected)return heading('05 / Share an experience','Where did<br><em>you go?</em>','Select a place before leaving a review. This keeps your visit linked to the right business.')+'<button class="primary" onclick="go(3)">Choose a place →</button>';if(c.before||c.ended)return heading('05 / Share an experience','Your trip,<br><em>at the right time.</em>',c.before?'Your trip has not started yet. Come back after your first visit.':'This trip has ended. Your saved experiences are in My profile.')+'<button class="primary" onclick="go(5)">Open my profile →</button>';let p=selected;return heading('05 / Leave a little knowledge behind','Your experience.<br><em>Someone else’s head start.</em>','Save your visit, update your budget and keep the memory on your profile.')+`<div class="layout"><section class="panel reviewpanel"><div class="reviewplace"><img src="assets/${p.category==='Food'?'dining':p.category==='Cafés'?'coffee':'park'}.jpg" alt="Illustrative place photo"><div><span class="badge">${p.city} · Fictional demo listing</span><h2>${p.icon} ${p.name}</h2></div></div><form id="reviewForm" onsubmit="submitReview(event)"><label>How was it?</label><div class="stars" role="group" aria-label="Choose a rating">${[1,2,3,4,5].map(i=>`<button type="button" aria-label="${i} stars" aria-pressed="${i===rating}" class="${i<=rating?'on':''}" onclick="setRating(${i})">★</button>`).join('')}</div><label>What should another student know?<textarea name="comment" required maxlength="1000" placeholder="The food, the price, the atmosphere…">${esc(reviewDraft.comment||'')}</textarea></label><div class="fields" style="margin:20px 0"><label>What you actually paid (€)<input name="amount" required type="number" min="0" max="100000" step="0.01" value="${esc(reviewDraft.amount??p.price)}"></label><label>Date of visit<input name="date" type="date" required min="${state.start}" max="${Budget.today()}" value="${reviewDraft.date||Budget.today()}"></label></div><label class="upload">↥ Add a receipt or menu photo<small>Optional · JPG, PNG or WebP · Up to 3 MB</small><input type="file" accept="image/jpeg,image/png,image/webp" onchange="loadReceipt(this)"><img id="receiptpreview" class="receiptpreview" alt="Receipt preview" ${receipt?`src="${receipt}"`:'hidden'}></label><p class="tiny">Hide personal details first. The resized photo is saved only on this browser with your experience, not uploaded to a server.</p><div class="notice">This visit will automatically create one expense. Your remaining budget and forecast will update together.</div><button class="primary" style="margin-top:20px" type="submit" id="saveReview">Save visit & update budget ✓</button></form></section><div>${forecast(c)}<div class="greenbox"><b>A memory worth keeping</b><br>Your review, actual price and receipt will appear together in My profile.</div></div></div>`}
function loadReceipt(input){let f=input.files[0];if(!f)return;if(f.size>3*1024*1024||!['image/jpeg','image/png','image/webp'].includes(f.type)){input.value='';toast('Choose a JPG, PNG or WebP under 3 MB.');return}receiptBusy=true;$('#saveReview').disabled=true;let reader=new FileReader();reader.onerror=()=>{receiptBusy=false;$('#saveReview').disabled=false;toast('The photo could not be read. Try another image.')};reader.onload=()=>{let img=new Image();img.onerror=()=>{receiptBusy=false;$('#saveReview').disabled=false;toast('This image could not be opened.')};img.onload=()=>{let canvas=document.createElement('canvas'),scale=Math.min(1,900/Math.max(img.width,img.height));canvas.width=img.width*scale;canvas.height=img.height*scale;canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);receipt=canvas.toDataURL('image/jpeg',.7);$('#receiptpreview').src=receipt;$('#receiptpreview').hidden=false;receiptBusy=false;$('#saveReview').disabled=false};img.src=reader.result};reader.readAsDataURL(f)}
function submitReview(e){e.preventDefault();if(receiptBusy||!selected||!state.created)return;let d=new FormData(e.target),amount=Number(d.get('amount')),date=d.get('date'),comment=String(d.get('comment')).trim();if(!comment||!Number.isFinite(amount)||amount<0||!checkVisit(date,Budget.calculate(state))){toast('Add a review and a valid visit date during your trip, no later than today.');return}let visit=id(),expenseId=id(),r={id:visit,place:selected.name,placeId:selected.id,city:selected.city,category:selected.category,comment,rating,amount,date,receipt,expenseId};state.reviews.push(r);state.expenses.push({id:expenseId,visitId:visit,title:selected.name,category:selected.category==='Cafés'?'Food':selected.category,amount,date});if(!persist()){state.reviews.pop();state.expenses.pop();return}selected=null;receipt=null;reviewDraft={};go(5);toast('Visit saved to My profile. Budget and forecast updated.')}
function profile(c){if(!state.created)return heading('Your personal space','A profile for<br><em>your next chapter.</em>','Your trip, spending history and shared experiences will live here.')+'<button class="primary" onclick="go(0)">Create my profile →</button>';return heading('Your personal space',`Hey ${esc(state.name)}.<br><em>Here’s your journey.</em>`,`${state.city} · ${state.start} → ${c.end} · ${Budget.lifestyles[state.profile][0]}`)+`<div class="profilebanner"><div><span class="avatar">${esc(state.name[0].toUpperCase())}</span><b>${esc(state.name)}</b><small>${state.housing} · Local browser profile</small></div><button class="secondary" onclick="go(0)">Edit my profile</button></div>${stats(c)}${c.remaining<0?'<div class="notice warning">You have spent more than your total budget. Your daily allowance is now zero.</div>':''}<div class="layout"><div><section class="panel"><h2 class="sectiontitle">Your past experiences <span>${state.reviews.length}</span></h2>${state.reviews.length?state.reviews.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(r=>`<article class="historycard"><div class="historyicon" aria-hidden="true">${r.category==='Activities'?'↗':'☕'}</div><div class="barrow"><b>${esc(r.place)}</b><span>${r.rating} ★</span></div><small>${esc(r.city||state.city)} · ${esc(r.date)} · ${euro(r.amount)}</small><p style="white-space:pre-wrap">${esc(r.comment)}</p>${r.receipt?`<details><summary>View receipt photo</summary><img class="receiptpreview" alt="Saved receipt for ${esc(r.place)}" src="${r.receipt}"></details>`:r.receiptAttached?'<small>The old version only previewed this receipt; the image was not stored.</small>':''}</article>`).join(''):'<div class="empty"><b>Your first story is waiting.</b><p>Choose a place, enjoy your visit and save the experience. It will appear here automatically.</p><button class="primary" onclick="go(3)">Find a place →</button></div>'}</section><details class="panel expensedrawer"><summary>Spending history · ${state.expenses.length} entries</summary>${state.expenses.length?state.expenses.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(e=>`<div class="expense"><div><b>${esc(e.title)}</b><small>${esc(e.date)} · ${esc(e.category)}</small></div><div><b>${euro(e.amount)}</b>${!e.visitId?`<button class="textbutton" onclick="deleteExpense('${e.id}')" aria-label="Delete expense">Delete</button>`:''}</div></div>`).join(''):'<p class="intro">No spending logged yet. Add a visit or your everyday expenses to start building your forecast.</p>'}</details>${expenseForm(c)}</div><div>${forecast(c)}<div class="greenbox"><b>Keep your forecast useful</b><br>Log all your expenses, including groceries and transport. After three completed days with entries, your forecast uses your recent spending pace.</div><p class="tiny">This profile is saved on this browser only. There is no online account or cross-device sync.</p></div></div>`}
function deleteExpense(expenseId){let old=state.expenses;state.expenses=old.filter(e=>e.id!==expenseId||e.visitId);if(persist()){render();toast('Expense removed. Budget updated.')}else state.expenses=old}
render();
